```cpp
#include <memory>
#include <utility>

class Animal {
private:
    std::string name_;
    std::string sound_;
public:
    // Constructor with move semantics
    Animal(std::string name, std::string sound)
        : name_(std::move(name)), sound_(std::move(sound)) {}

    // Rule of five (or zero)
    Animal(const Animal&) = default;             // copy ctor
    Animal& operator=(const Animal&) = default;  // copy assign
    Animal(Animal&&) = default;                  // move ctor
    Animal& operator=(Animal&&) = default;       // move assign
    virtual ~Animal() = default;                 // virtual dtor!

    const std::string& name() const { return name_; }

    virtual std::string speak() const {
        return name_ + " says " + sound_;
    }

    bool operator==(const Animal& other) const {
        return name_ == other.name_;
    }

    friend std::ostream& operator<<(std::ostream& os, const Animal& a) {
        return os << "Animal(" << a.name_ << ")";
    }
};
```

