// Derived class
class Dog : public Animal {
    std::string breed_;
public:
    Dog(std::string name, std::string breed)
        : Animal(std::move(name), "Woof"), breed_(std::move(breed)) {}

    std::string speak() const override {   // override is checked!
        return Animal::speak() + "!";
    }
    std::string breed() const { return breed_; }
};

// Abstract class (pure virtual)
class Shape {
public:
    virtual double area() const = 0;        // pure virtual
    virtual double perimeter() const = 0;  // pure virtual
    virtual ~Shape() = default;

    void describe() const {    // non-virtual method
        std::cout << "Area=" << area() << "\n";
    }
};
```

- `virtual` enables runtime polymorphism
- `override` keyword verifies you're actually overriding
- `= 0` makes a function pure virtual → class is abstract
- Always declare destructor `virtual` in base classes used polymorphically

```cpp
#include <memory>

// unique_ptr — exclusive ownership, zero overhead
auto up = std::make_unique<Dog>("Rex", "Labrador");
up->speak();
// auto up2 = up;         // ERROR: cannot copy
auto up3 = std::move(up); // transfer ownership

// shared_ptr — shared ownership, ref-counted
auto sp1 = std::make_shared<Dog>("Buddy", "Poodle");
auto sp2 = sp1;   // ref count = 2
sp1.use_count();  // 2
// Destroyed when ref count hits 0

// weak_ptr — non-owning observer (breaks cycles)
std::weak_ptr<Dog> wp = sp1;
if (auto locked = wp.lock()) {
    locked->speak();    // safe: sp1 still alive
}

// Custom deleter
auto file = std::unique_ptr<FILE, decltype(&fclose)>(
    fopen("file.txt", "r"), fclose
);
```

Prefer `make_unique` and `make_shared` — exception-safe and more efficient.

